"""Local web dashboard for presenting the OrbitTech evaluation lab.

Run ``python demo_app.py`` and open http://127.0.0.1:8000.  The dashboard is
dependency-free: it reads the benchmark artifacts already generated by the
lab, exposes the retrieval trace for each case, and can run a live RAG query
when a valid ``.env`` is configured.
"""

from __future__ import annotations

import argparse
import json
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any
from urllib.parse import parse_qs, urlparse

from domain_assistant import DomainAssistant
from solution.solution import QAPair, RAGASEvaluator


ROOT = Path(__file__).resolve().parent
BENCHMARK_PATH = ROOT / "artifacts" / "benchmark_results.json"
ACTUAL_PATH = ROOT / "artifacts" / "actual_answers.json"
GOLDEN_PATH = ROOT / "golden_dataset.json"
CORPUS_PATH = ROOT / "data" / "technology_store"


def read_json(path: Path) -> dict[str, Any]:
    """Read a JSON object from a known lab artifact."""

    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise ValueError(f"{path.name} must contain a JSON object")
    return value


def load_dashboard() -> dict[str, Any]:
    """Return only the fields required by the dashboard overview."""

    benchmark = read_json(BENCHMARK_PATH)
    summary = benchmark.get("summary")
    results = benchmark.get("results")
    if not isinstance(summary, dict) or not isinstance(results, list):
        raise ValueError("benchmark_results.json is missing summary or results")
    cases = [
        {
            key: result.get(key)
            for key in (
                "id", "difficulty", "question", "overall", "passed", "failure_type",
                "faithfulness", "relevance", "completeness", "context_recall",
                "context_precision",
            )
        }
        for result in results
        if isinstance(result, dict)
    ]
    return {"summary": summary, "cases": cases, "failure_analysis": benchmark.get("failure_analysis", {})}


def load_case(case_id: str) -> dict[str, Any]:
    """Join one scored result to its auditable RAG retrieval trace."""

    benchmark = read_json(BENCHMARK_PATH)
    actual = read_json(ACTUAL_PATH)
    result = next(
        (item for item in benchmark.get("results", []) if item.get("id") == case_id),
        None,
    )
    trace = next(
        (item for item in actual.get("answers", []) if item.get("id") == case_id),
        None,
    )
    if not isinstance(result, dict) or not isinstance(trace, dict):
        raise ValueError(f"No case with id {case_id!r}")
    return {
        "result": result,
        "retrieved_contexts": trace.get("retrieved_contexts", []),
    }


def evaluate_answer(case_id: str, answer: str) -> dict[str, Any]:
    """Score an edited answer against one golden item for presentation use."""

    golden = read_json(GOLDEN_PATH)
    actual = read_json(ACTUAL_PATH)
    gold = next((item for item in golden.get("qa_pairs", []) if item.get("id") == case_id), None)
    trace = next((item for item in actual.get("answers", []) if item.get("id") == case_id), None)
    if not isinstance(gold, dict) or not isinstance(trace, dict):
        raise ValueError(f"No case with id {case_id!r}")
    contexts = [item.get("text", "") for item in trace.get("retrieved_contexts", []) if isinstance(item, dict)]
    gold_context = "\n\n".join(
        item.get("text", "") for item in gold.get("contexts", []) if isinstance(item, dict)
    )
    pair = QAPair(
        question=str(gold["question"]),
        expected_answer=str(gold["expected_answer"]),
        context=gold_context,
        metadata={"id": case_id},
        retrieved_contexts=contexts,
    )
    result = RAGASEvaluator().run_full_eval(
        answer=answer,
        question=pair.question,
        context=pair.context or "",
        expected=pair.expected_answer,
        contexts=pair.retrieved_contexts,
    )
    return {
        "faithfulness": result.faithfulness,
        "relevance": result.relevance,
        "completeness": result.completeness,
        "context_recall": result.context_recall,
        "context_precision": result.context_precision,
        "overall": result.overall_score(),
        "passed": result.passed,
        "failure_type": result.failure_type,
    }


def run_live_query(question: str) -> dict[str, Any]:
    """Run only the system under evaluation; no golden answer is consulted."""

    assistant = DomainAssistant.from_corpus(CORPUS_PATH)
    response = assistant.answer_with_trace(question)
    return {
        "answer": response.actual_answer,
        "retrieved_contexts": [
            {
                "chunk_id": chunk.chunk_id,
                "source_doc": chunk.source_doc,
                "text": chunk.text,
                "score": round(chunk.score, 4),
            }
            for chunk in response.retrieved_chunks
        ],
    }


class DemoHandler(BaseHTTPRequestHandler):
    """Serve the single-page presentation UI and narrowly scoped JSON APIs."""

    server_version = "OrbitTechDemo/1.0"

    def log_message(self, format: str, *args: Any) -> None:
        # Keep the terminal clean during a presentation.
        return

    def send_json(self, status: HTTPStatus, body: dict[str, Any]) -> None:
        encoded = json.dumps(body, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(encoded)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(encoded)

    def do_GET(self) -> None:  # noqa: N802 - BaseHTTPRequestHandler contract
        route = urlparse(self.path)
        try:
            if route.path == "/":
                page = PAGE.encode("utf-8")
                self.send_response(HTTPStatus.OK)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Content-Length", str(len(page)))
                self.end_headers()
                self.wfile.write(page)
            elif route.path == "/api/dashboard":
                self.send_json(HTTPStatus.OK, load_dashboard())
            elif route.path == "/api/case":
                case_id = parse_qs(route.query).get("id", [""])[0]
                self.send_json(HTTPStatus.OK, load_case(case_id))
            else:
                self.send_json(HTTPStatus.NOT_FOUND, {"error": "Route not found"})
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            self.send_json(HTTPStatus.INTERNAL_SERVER_ERROR, {"error": str(exc)})

    def do_POST(self) -> None:  # noqa: N802 - BaseHTTPRequestHandler contract
        route = urlparse(self.path)
        try:
            content_length = int(self.headers.get("Content-Length", "0"))
            if content_length > 20_000:
                raise ValueError("Request is too large")
            payload = json.loads(self.rfile.read(content_length) or b"{}")
            if not isinstance(payload, dict):
                raise ValueError("Request body must be a JSON object")
            if route.path == "/api/evaluate":
                case_id = str(payload.get("id", "")).strip()
                answer = str(payload.get("answer", "")).strip()
                if not case_id or not answer:
                    raise ValueError("A case ID and answer are required")
                self.send_json(HTTPStatus.OK, evaluate_answer(case_id, answer))
            elif route.path == "/api/live-query":
                question = str(payload.get("question", "")).strip()
                if not question:
                    raise ValueError("Please enter a question")
                if len(question) > 1_500:
                    raise ValueError("Question must be at most 1,500 characters")
                self.send_json(HTTPStatus.OK, run_live_query(question))
            else:
                self.send_json(HTTPStatus.NOT_FOUND, {"error": "Route not found"})
        except (OSError, RuntimeError, ValueError, json.JSONDecodeError) as exc:
            self.send_json(HTTPStatus.BAD_REQUEST, {"error": str(exc)})


